  function baueSeiteSync(wurzel) {
    /* Synchronisation */
    baueNextcloudKonto(wurzel);
    const sy = abschnitt(_("Calendars and contacts"),
      _("Multiple calendars") + ". " + _("One address book") + ".");
    sy.id = "nextcloud-kalender-kontakte";
    const status = el("p", "sync-status");
    status.id = "sync-status";
    sy.append(status);
    const wahl = el("div", "sync-wahl");
    wahl.id = "sync-wahl";
    sy.append(wahl);

    const startHak = document.createElement("input");
    startHak.type = "checkbox";
    startHak.id = "sync-beim-start";
    startHak.checked = !!DATEN.einstellungen.sync.beimStart;
    startHak.addEventListener("change", () => {
      DATEN.einstellungen.sync.beimStart = startHak.checked;
      planeSpeichern();
    });
    const startZeile = el("label", "hak");
    startZeile.append(startHak,
      document.createTextNode(" " + _("Synchronize automatically at startup")));
    sy.append(startZeile);

    const syncKnopf = knopf(_("Synchronize now"), "", () => starteSync(false));
    syncKnopf.id = "sync-jetzt";
    const syncReihe = el("div", "knopfreihe");
    syncReihe.append(syncKnopf);
    sy.append(syncReihe);
    wurzel.append(sy);

    if (!Bruecke.vorhanden) {
      status.textContent = _("Import, export and synchronization are available only " +
        "in the installed application.");
      syncKnopf.disabled = true;
    } else if (letzterEdsStatus) {
      fuelleEdsAuswahl(letzterEdsStatus);
    } else {
      status.textContent = _("Checking online accounts …");
    }
    baueBriefkasten(wurzel);
  }

